/* All coordinates use the fixed 1200 × 680 stimulus coordinate system. */
const app=document.querySelector('#app');
const W=1200,H=680,sessionId=crypto.randomUUID();
let trial=0,records=[],events=[],active=false,startMono=0,startISO='',errors=0,canvas,ctx,transitionTimer,attempt=1;
const targetFor=n=>n<=5?{x:987,y:159,w:150,h:44,location:'upper-right',state:'A'}:{x:57,y:527,w:150,h:44,location:'lower-left',state:'B'};
function intro(){app.innerHTML=`<div class="intro"><section><div class="eyebrow">SPATIAL ADAPTATION / STUDY 001</div><h1>A familiar space.<br>A new search.</h1><p>Explore how experience shapes visual search in a spacecraft control panel.</p><div class="facts"><div><strong>08</strong><span>Search trials</span></div><div><strong>01</strong><span>Visual environment</span></div><div><strong>Your pace</strong><span>No time limit</span></div></div></section><section class="brief"><div class="eyebrow">PARTICIPANT INSTRUCTIONS</div><h2>Spatial Adaptation Study</h2><div class="step"><b>01</b><div><strong>Find O₂ WARNING</strong>You will see a spacecraft control panel. Locate and select the O₂ WARNING indicator as quickly and accurately as possible.</div></div><div class="step"><b>02</b><div><strong>Keep searching</strong>The environment may change during the experiment. Complete all eight trials.</div></div><div class="step"><b>03</b><div><strong>Review your results</strong>Your results appear after the final trial.</div></div><button class="primary" id="begin">Begin Experiment</button><p class="note">Use a mouse or touch. On a small screen, rotate to landscape. Data stays in this session unless you download it.</p></section></div>`;document.querySelector('#begin').onclick=()=>{trial=1;showTrial()}}
function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(x,y,w,h)}
function text(t,x,y,size=12,color='#9daead'){ctx.fillStyle=color;ctx.font=`${size}px monospace`;ctx.fillText(t,x,y)}
function box(x,y,w,h,label){rect(x,y,w,h,'#1c282d');ctx.strokeStyle='#435158';ctx.strokeRect(x+.5,y+.5,w-1,h-1);text(label,x+16,y+25,13,'#a8b9b8');for(const dx of [8,w-8])for(const dy of [8,h-8]){ctx.beginPath();ctx.arc(x+dx,y+dy,2,0,7);ctx.fillStyle='#667277';ctx.fill()}}
function indicator(x,y,label,amber=false,w=150){rect(x,y,w,44,'#0c1519');ctx.strokeStyle='#425055';ctx.strokeRect(x+.5,y+.5,w-1,43);rect(x+9,y+16,8,10,amber?'#c19b54':'#719e93');text(label,x+25,y+28,13,amber?'#dbbd80':'#a6c5bc')}
function gauge(x,y,label,value){ctx.strokeStyle='#53676a';ctx.lineWidth=9;ctx.beginPath();ctx.arc(x,y,43,Math.PI*.8,Math.PI*2.2);ctx.stroke();ctx.strokeStyle='#85b1a0';ctx.beginPath();ctx.arc(x,y,43,Math.PI*.8,Math.PI*1.8);ctx.stroke();ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+20,y-26);ctx.stroke();ctx.lineWidth=1;text(value,x-19,y+25,17,'#d0dfd9');text(label,x-39,y+65,11)}
function drawPanel(){ctx=canvas.getContext('2d');rect(0,0,W,H,'#121b20');rect(12,12,1176,42,'#28373c');text('KEPLER  /  ORBITAL SYSTEMS',32,39,16,'#c1d3ce');text('FLIGHT DECK  04     |     AUXILIARY CONTROL',730,39,13);box(25,70,350,218,'PROPULSION / ENGINE TELEMETRY');gauge(93,169,'THRUST','82.4');gauge(206,169,'PRESSURE','1.02');gauge(312,169,'FLOW','67.8');box(393,70,405,310,'NAVIGATION / RELATIVE POSITION');rect(409,113,373,247,'#0c1e24');ctx.strokeStyle='#25424b';for(let x=425;x<780;x+=30){ctx.beginPath();ctx.moveTo(x,114);ctx.lineTo(x,359);ctx.stroke()}for(let y=130;y<358;y+=30){ctx.beginPath();ctx.moveTo(410,y);ctx.lineTo(781,y);ctx.stroke()}for(let r=30;r<=100;r+=35){ctx.beginPath();ctx.arc(595,233,r,0,7);ctx.stroke()}ctx.strokeStyle='#93c4b6';ctx.beginPath();ctx.moveTo(470,308);ctx.lineTo(555,280);ctx.lineTo(596,226);ctx.lineTo(714,157);ctx.stroke();text('+',587,242,26,'#d4ddc1');text('RANGE  024.8 KM',424,341,12);text('VEC  083.2',647,341,12);box(818,70,357,218,'ENVIRONMENT / LIFE SUPPORT');indicator(837,108,'CO₂ LEVEL');indicator(1003,108,'CABIN TEMP');indicator(837,219,'AIRFLOW');indicator(1003,219,'FILTER SYS',true);box(25,306,350,190,'POWER DISTRIBUTION');['BUS A','BUS B','RESERVE'].forEach((l,i)=>{text(l,43,359+i*47,12);rect(135,344+i*47,205,16,'#101b1e');rect(135,344+i*47,160-i*30,16,'#658c83');text(['98%','76%','62%'][i],290,357+i*47,11,'#cce1d6')});box(818,306,357,190,'COMMUNICATIONS / UPLINK');text('S-BAND   2287.50 MHz',839,363,18,'#b4d8cb');text('LINK STABLE    /    SIGNAL 94%',839,393,13);for(let i=0;i<22;i++)rect(839+i*14,461-(i*17%40),7,15+(i*17%40),'#739c90');box(393,398,405,255,'ATTITUDE / MANUAL OVERRIDE');['ROLL','PITCH','YAW'].forEach((l,i)=>{text(l,421+i*124,450,12);ctx.beginPath();ctx.arc(448+i*124,493,28,0,7);ctx.fillStyle='#0c1418';ctx.fill();ctx.strokeStyle='#597176';ctx.stroke();rect(445+i*124,472,6,27,'#8daba2')});indicator(415,579,'AUTO HOLD');indicator(621,579,'RCS ARMED',true);box(25,514,350,139,'');indicator(57,588,'PUMP STATUS');indicator(215,588,'THERMAL',true,140);box(818,514,357,139,'SYSTEMS / AUXILIARY');indicator(837,552,'DOCK LOCK',true);indicator(1003,552,'FUEL VALVE');text('MODE  STANDBY     SEQ  0082',840,629,13);const t=targetFor(trial);indicator(t.x,t.y,'O₂ WARNING',true,t.w)}
function showTrial(){active=false;errors=0;app.innerHTML=`<section class="trial-screen"><div class="trialtop"><h1>Trial ${trial} <span style="color:#81958d">of 8</span></h1><p>Find: <strong class="target-name">O₂ WARNING</strong></p></div><div class="panel-scroll"><div class="panelwrap"><canvas width="1200" height="680" aria-label="Spacecraft control panel. Find and select O₂ WARNING."></canvas><div class="overlay" id="mask"><strong>Get ready</strong></div></div></div></section>`;canvas=app.querySelector('canvas');drawPanel();canvas.addEventListener('pointerdown',handleClick);transitionTimer=setTimeout(()=>{const mask=app.querySelector('#mask');if(!mask)return;mask.remove();requestAnimationFrame(()=>{startMono=performance.now();startISO=new Date().toISOString();active=true})},450)}
function handleClick(e){if(!active||e.button!==0)return;const b=canvas.getBoundingClientRect(),x=(e.clientX-b.left)*W/b.width,y=(e.clientY-b.top)*H/b.height,t=targetFor(trial),hit=x>=t.x&&x<=t.x+t.w&&y>=t.y&&y<=t.y+t.h;const now=performance.now(),clickISO=new Date().toISOString();const event={session_id:sessionId,trial,attempt,trial_start_timestamp:startISO,click_timestamp:clickISO,reaction_time_ms:Math.round((now-startMono)*1000)/1000,click_x:Math.round(x*100)/100,click_y:Math.round(y*100)/100,target_clicked:hit,incorrect_clicks:errors+(hit?0:1),target_location:t.location,environment_state:t.state,event_type:'click'};events.push(event);if(!hit){errors++;return}active=false;records.push(event);const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML='<strong>Target Found</strong>';app.querySelector('.panelwrap').append(overlay);transitionTimer=setTimeout(()=>{if(trial===8)results();else{trial++;attempt=1;showTrial()}},550)}
document.addEventListener('visibilitychange',()=>{if(!document.hidden||!trial||records.length===8)return;clearTimeout(transitionTimer);if(!active&&records.at(-1)?.trial===trial){if(trial===8)results();else{trial++;attempt=1;showPaused()}return}if(active){events.push({session_id:sessionId,trial,attempt,event_type:'interrupted',click_timestamp:new Date().toISOString(),trial_start_timestamp:startISO,environment_state:targetFor(trial).state});attempt++}showPaused()});
function showPaused(){active=false;app.innerHTML='<section class="brief paused"><h2>Study paused</h2><p>The page was hidden. Resume to restart the current trial so time away is not counted. Any interrupted attempt is included in the downloaded event log.</p><button id="resume">Resume trial</button></section>';app.querySelector('#resume').onclick=showTrial}
const secs=n=>(n/1000).toFixed(2);
function download(kind){const rows=kind==='trials'?records:events;const keys=['session_id','trial','attempt','event_type','trial_start_timestamp','click_timestamp','reaction_time_ms','click_x','click_y','target_clicked','incorrect_clicks','target_location','environment_state'];const csv=[keys.join(','),...rows.map(r=>keys.map(k=>JSON.stringify(r[k]??'')).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`neuronav-${sessionId}-${kind}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function results(){active=false;const baseline=records.slice(0,5).reduce((s,r)=>s+r.reaction_time_ms,0)/5,change=records[5].reaction_time_ms-records[4].reaction_time_ms,totalErrors=events.filter(r=>r.event_type==='click'&&!r.target_clicked).length;const max=Math.max(1,Math.ceil(Math.max(...records.map(r=>r.reaction_time_ms/1000))*1.15));const px=i=>52+i*58,py=v=>250-v/max*195;const chart=`<svg class="chart" viewBox="0 0 510 306" role="img" aria-label="Reaction time in seconds across eight trials. Environment changes at trial six."><text x="12" y="20">Reaction time (seconds)</text>${[0,.25,.5,.75,1].map(f=>`<line x1="52" x2="465" y1="${py(max*f)}" y2="${py(max*f)}" stroke="#33443f"/><text x="10" y="${py(max*f)+4}">${(max*f).toFixed(1)}</text>`).join('')}<line x1="342" x2="342" y1="40" y2="258" stroke="#b8ed70" stroke-dasharray="4 5"/><text x="295" y="36" style="fill:#b8ed70">Environment Changed</text><polyline points="${records.map((r,i)=>`${px(i)},${py(r.reaction_time_ms/1000)}`).join(' ')}" fill="none" stroke="#b8ed70" stroke-width="2.5"/>${records.map((r,i)=>`<circle cx="${px(i)}" cy="${py(r.reaction_time_ms/1000)}" r="5" fill="#b8ed70"><title>Trial ${i+1}: ${secs(r.reaction_time_ms)} seconds</title></circle><text x="${px(i)-4}" y="278">${i+1}</text>`).join('')}<text x="236" y="302">Trial</text></svg>`;app.innerHTML=`<div class="resulthead"><div><div class="eyebrow">SESSION COMPLETE / 08 OF 08</div><h1>NeuroNav Results</h1><p>Spatial Adaptation Study 001</p></div><button class="secondary" id="again">New session</button></div><div class="metrics"><div class="metric"><span>Original environment · mean</span><strong>${secs(baseline)} s</strong></div><div class="metric"><span>Trial 6 − Trial 5</span><strong>${change>=0?'+':''}${secs(change)} s</strong></div><div class="metric"><span>Incorrect clicks · all attempts</span><strong>${totalErrors}</strong></div></div><div class="resultsgrid"><section class="chartcard"><h3>Your search over time</h3>${chart}</section><section class="tablecard"><h3>Trial detail</h3><table><thead><tr><th>Trial</th><th>Environment</th><th>Time</th><th>Errors</th></tr></thead><tbody>${records.map(r=>`<tr class="${r.trial===6?'changed':''}"><td>${r.trial}</td><td>${r.environment_state==='A'?'Original':'Changed'}</td><td>${secs(r.reaction_time_ms)} s</td><td>${r.incorrect_clicks}</td></tr>`).join('')}</tbody></table></section></div><p class="interpretation">The target moved from the upper-right to the lower-left at Trial 6. A rise at Trial 6 followed by lower times may be consistent with adaptation. Eight trials from one session do not establish a learning effect or support a diagnosis.</p><div class="actions"><button id="export">Download trial data</button><button class="secondary" id="events">Download click log</button></div><p class="note">Coordinates are relative to the 1200 × 680 panel. Timing uses the browser’s monotonic clock. Hidden-page attempts are restarted and flagged in the click log. Data is not saved after you leave this page.</p>`;app.querySelector('#export').onclick=()=>download('trials');app.querySelector('#events').onclick=()=>download('events');app.querySelector('#again').onclick=()=>location.reload()}
intro();

